/* groups: margin-top, padding-left, border-bottom... */
function cssInfo(p){
 if(C[p])return C[p];
 var m=p.match(/^(margin|padding)-(top|right|bottom|left)$/);
 if(m)return [(m[1]==='margin'?'Space OUTSIDE the box on the ':'Space INSIDE the box on the ')+m[2]+' side only.',(m[1]==='margin'?'Box ke BAHAR ':'Box ke ANDAR ')+'sirf '+m[2]+' taraf ki jagah.',p+':20px;'];
 m=p.match(/^border-(top|right|bottom|left)(-.*)?$/);
 if(m)return ['A border line on the '+m[1]+' side only.','Sirf '+m[1]+' taraf ki border lakeer.',p+':2px solid #333;'];
 if(/^border-/.test(p))return ['Fine control of the border: color, width or style.','Border ka alag alag control: rang, motai ya style.',''];
 if(/^background-/.test(p))return ['Fine control of the background.','Background ka alag alag control.',''];
 if(/^font-/.test(p))return ['A font setting.','Font ki ek setting.',''];
 if(/^grid-/.test(p))return ['A grid layout setting.','Grid layout ki ek setting.',''];
 if(/^flex-/.test(p))return ['A flexbox setting.','Flexbox ki ek setting.',''];
 if(/^(animation|transition)-/.test(p))return ['Fine control of motion or timing.','Motion ya samay ka alag control.',''];
 if(/^(overflow|text|list)-/.test(p))return ['A detail setting related to '+p.split('-')[0]+'.',p.split('-')[0]+' se judi ek chhoti setting.',''];
 if(p.charAt(0)==='-'&&p.charAt(1)==='-')return ['A CSS variable you made yourself. Read it with var('+p+').','Aapka banaya CSS variable. Use karne ke liye var('+p+') likho.',''];
 return null}
