var P='<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>My page</title>\n';
var LESSONS=[
{t:['Your first web page','Aapka pehla web page'],
 i:['A web page is just text with tags. Tags look like <h1> and they tell the browser what each piece is. Change the words below and watch the preview update live.','Web page bas text hai jisme tags lagte hain. Tag aise dikhte hain <h1> aur browser ko batate hain ki ye kya hai. Neeche ke shabd badlo aur preview ko turant badalte dekho.'],
 code:'<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <title>My first page</title>\n</head>\n<body>\n  <h1>Hello, world!</h1>\n  <p>This is my first paragraph.</p>\n</body>\n</html>\n',
 tasks:[['Change the h1 text to your own name','h1 ka text badal kar apna naam likho','h1',/<h1>(?!Hello, world!<)[^<]+<\/h1>/i],['Add a second paragraph with <p>','Ek aur paragraph <p> se jodo','p',/<p>[\s\S]*<\/p>[\s\S]*<p>[\s\S]*<\/p>/i],['Add an <h2> heading','Ek <h2> heading jodo','h2',/<h2>[\s\S]*<\/h2>/i]],
 tip:['Hover over any coloured word in the code to see what it means.','Code ke kisi bhi rangeen shabd par mouse rakho, uska matlab dikhega.']},
{t:['Text, links and emphasis','Text, links aur zor dena'],
 i:['Make words bold with <strong>, slanted with <em> and clickable with <a href="...">. A link needs an address in href. Put target="_blank" to open a new tab.','Shabd ko bold <strong>, tirchha <em> aur click hone wala <a href="..."> se banate hain. Link ko href me address chahiye. Naye tab ke liye target="_blank" likho.'],
 code:'<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <title>Text and links</title>\n</head>\n<body>\n  <h1>About me</h1>\n  <p>I like <strong>cricket</strong> and <em>coding</em>.</p>\n  <p>Visit <a href="https://ourworldhive.com">Ourworldhive</a>.</p>\n</body>\n</html>\n',
 tasks:[['Make one more word bold with <strong>','Ek aur shabd <strong> se bold karo','strong',/<strong>[\s\S]*<\/strong>[\s\S]*<strong>[\s\S]*<\/strong>/i],['Make your link open in a new tab (target="_blank")','Link ko naye tab me kholo (target="_blank")','target',/target\s*=\s*["']_blank["']/i],['Add a line break with <br> inside a paragraph','Paragraph me <br> se nayi line lao','br',/<br\s*\/?>/i]],
 tip:['Always write meaningful link text. "Click here" is poor, "Download the price list" is good.','Link ka text matlab wala likho. "Yahan click karo" kamzor hai, "Price list download karo" accha hai.']},
{t:['Images and lists','Images aur lists'],
 i:['<img> shows a picture and needs src (where the file is) and alt (a description). <ul> makes bullets and <ol> makes numbers, with <li> for each item. The picture below is drawn from code, so it works without any file.','<img> picture dikhata hai, isko src (file kahan hai) aur alt (description) chahiye. <ul> bullet aur <ol> number banata hai, har item <li> me. Neeche ki picture code se bani hai, isliye bina kisi file ke chalti hai.'],
 code:'<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <title>Images and lists</title>\n</head>\n<body>\n  <h1>My day</h1>\n  <img alt="A blue square" width="120"\n    src="data:image/svg+xml,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 10 10\'%3E%3Crect width=\'10\' height=\'10\' fill=\'%2300aaff\'/%3E%3C/svg%3E">\n  <h2>Things to do</h2>\n  <ul>\n    <li>Learn HTML</li>\n    <li>Learn CSS</li>\n  </ul>\n</body>\n</html>\n',
 tasks:[['Add a third <li> to the list','List me teesra <li> jodo','li',/(<li>[\s\S]*?<\/li>[\s\S]*?){3}/i],['Add an ordered list <ol> with 2 steps','2 steps wali <ol> list jodo','ol',/<ol>[\s\S]*<li>[\s\S]*<li>[\s\S]*<\/ol>/i],['Change the alt text of the image','Image ka alt text badlo','alt',/alt\s*=\s*["'](?!A blue square)[^"']+["']/i]],
 tip:['Alt text helps blind users and Google Images. Describe what the picture shows.','Alt text nabeena logon aur Google Images ke kaam aata hai. Likho ki picture me kya hai.']},
{t:['CSS: colors and fonts','CSS: rang aur font'],
 i:['CSS is the paint. It lives inside <style>. A rule has a selector (which elements), then properties in braces. Example: h1 { color: red; }. Hover over each property to learn what it does.','CSS rang-rogan hai. Ye <style> ke andar likhte hain. Rule me selector (kin elements par) aur braces me properties hoti hain. Jaise h1 { color: red; }. Har property par mouse rakh kar seekho wo kya karti hai.'],
 code:P+'  <style>\n    body {\n      font-family: Georgia, serif;\n      background-color: #fff8e7;\n      color: #333;\n    }\n    h1 {\n      color: #d6336c;\n      text-align: center;\n    }\n  </style>\n</head>\n<body>\n  <h1>Styled heading</h1>\n  <p>CSS changes how things look.</p>\n</body>\n</html>\n',
 tasks:[['Change the h1 color','h1 ka color badlo','color',/h1\s*\{[^}]*color\s*:[ ]*(?![ ]|#d6336c)[^;}]+/i],['Make paragraphs bigger with font-size','font-size se paragraph bade karo','font-size',/p\s*\{[^}]*font-size/i],['Add a class rule like .note { ... } and use it','.note { ... } jaisa class rule banao aur use karo','class',/\.[a-z][\w-]*\s*\{[\s\S]*class\s*=/i]],
 tip:['Use colour names (red), hex (#ff0000), rgb() or hsl(). Hover over a colour to see a swatch.','Rang ke naam (red), hex (#ff0000), rgb() ya hsl() use karo. Rang par mouse rakho to swatch dikhta hai.']},
{t:['The box model','Box model (margin, padding, border)'],
 i:['Every element is a box: content, then padding (inside space), then border, then margin (outside space). Understanding this fixes most layout problems. Change the numbers and see the box change.','Har element ek box hai: content, fir padding (andar ki jagah), fir border, fir margin (bahar ki jagah). Ye samajh lo to layout ki zyadatar dikkatein khatam. Numbers badlo aur box badalte dekho.'],
 code:P+'  <style>\n    * { box-sizing: border-box; }\n    body { font-family: system-ui, sans-serif; background: #eef2f7; }\n    .card {\n      width: 260px;\n      margin: 30px auto;\n      padding: 20px;\n      border: 3px solid #4c6ef5;\n      border-radius: 16px;\n      background: white;\n      box-shadow: 0 8px 20px rgba(0,0,0,.15);\n    }\n  </style>\n</head>\n<body>\n  <div class="card">\n    <h2>Card</h2>\n    <p>Padding is inside, margin is outside.</p>\n  </div>\n</body>\n</html>\n',
 tasks:[['Increase the padding to 40px','padding badha kar 40px karo','padding',/padding\s*:\s*(?:[4-9]\d|\d{3,})px/i],['Change border-radius to make a circle-ish look','border-radius badal kar gol shape lao','border-radius',/border-radius\s*:[ ]*(?![ ]|16px)[^;]+/i],['Add a second .card div','Doosra .card div jodo','card',/(class\s*=\s*["']card["'][\s\S]*){2}/i]],
 tip:['margin: 0 auto centers a box that has a width. This is the most used trick in CSS.','margin: 0 auto width wale box ko beech me laata hai. CSS ki sabse zyada use hone wali trick.']},
{t:['Flexbox layout','Flexbox se layout'],
 i:['display: flex puts children in a row. Then justify-content spreads them and align-items centers them up and down. gap adds space between. flex-wrap lets them wrap on small screens.','display: flex bachcho ko ek row me rakhta hai. Fir justify-content unhe failata hai aur align-items upar neeche beech me laata hai. gap beech me jagah deta hai. flex-wrap chhoti screen par agli line me bhejta hai.'],
 code:P+'  <style>\n    body { font-family: system-ui, sans-serif; margin: 0; }\n    nav {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 14px 20px;\n      background: #1b1f3b;\n      color: white;\n    }\n    .row { display: flex; gap: 12px; padding: 20px; flex-wrap: wrap; }\n    .box { flex: 1; min-width: 120px; padding: 24px; background: #ffd43b; border-radius: 12px; text-align: center; }\n  </style>\n</head>\n<body>\n  <nav><b>MyShop</b><span>Menu</span></nav>\n  <div class="row">\n    <div class="box">One</div>\n    <div class="box">Two</div>\n    <div class="box">Three</div>\n  </div>\n</body>\n</html>\n',
 tasks:[['Add a fourth .box','Chautha .box jodo','box',/(class\s*=\s*["']box["'][\s\S]*){4}/i],['Change justify-content on the nav to center','nav ka justify-content center karo','justify-content',/justify-content\s*:\s*center/i],['Make .row stack vertically with flex-direction: column','.row ko flex-direction: column se khada karo','flex-direction',/flex-direction\s*:\s*column/i]],
 tip:['Try the Mobile button above the preview to see how flex-wrap adapts.','Preview ke upar Mobile button dabao aur dekho flex-wrap kaise adjust hota hai.']},
{t:['Buttons, hover and animation','Buttons, hover aur animation'],
 i:[':hover applies styles when the mouse is over an element. transition makes the change smooth. transform moves or scales. Move your mouse over the button in the preview.',':hover tab lagta hai jab mouse element par ho. transition badlav ko smooth banata hai. transform khiskata ya bada karta hai. Preview me button par mouse le jao.'],
 code:P+'  <style>\n    body { display: grid; place-items: center; height: 100vh; margin: 0; background: #0b1020; }\n    .btn {\n      padding: 14px 28px;\n      border: 0;\n      border-radius: 999px;\n      background: linear-gradient(135deg, #ff6b6b, #fcc419);\n      color: #1b1030;\n      font-size: 18px;\n      font-weight: 700;\n      cursor: pointer;\n      transition: transform .2s, box-shadow .2s;\n    }\n    .btn:hover {\n      transform: scale(1.1);\n      box-shadow: 0 10px 30px rgba(255,200,0,.5);\n    }\n  </style>\n</head>\n<body>\n  <button class="btn">Hover me</button>\n</body>\n</html>\n',
 tasks:[['Change the hover scale to 1.25','Hover ka scale 1.25 karo','scale',/scale\(\s*1\.2[5-9]|scale\(\s*1\.[3-9]/i],['Add :active with transform: scale(.95)',':active me transform: scale(.95) lagao','active',/:active\s*\{[^}]*scale/i],['Add an animation with @keyframes','@keyframes se animation jodo','keyframes',/@keyframes[\s\S]*animation\s*:/i]],
 tip:['Keep animations short (0.2 to 0.4 seconds) so the page feels fast.','Animation chhote rakho (0.2 se 0.4 second) taaki page tez lage.']},
{t:['Forms and inputs','Forms aur inputs'],
 i:['Forms collect information. Each <input> has a type. A <label for="..."> connects text to its input, so clicking the label selects the box. required stops sending when empty.','Forms jaankari lete hain. Har <input> ka ek type hota hai. <label for="..."> text ko input se jodta hai, label par click karne se box chun jaata hai. required khali hone par bhejne se rokta hai.'],
 code:P+'  <style>\n    body { font-family: system-ui, sans-serif; background: #f1f3f5; }\n    form { max-width: 320px; margin: 24px auto; padding: 20px; background: white; border-radius: 14px; display: grid; gap: 10px; }\n    input, select, button { padding: 10px; font-size: 16px; border: 1px solid #ccc; border-radius: 8px; }\n    button { background: #364fc7; color: white; border: 0; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <form>\n    <label for="n">Name</label>\n    <input id="n" type="text" placeholder="Your name" required>\n    <label for="e">Email</label>\n    <input id="e" type="email" placeholder="you@example.com">\n    <button type="submit">Send</button>\n  </form>\n</body>\n</html>\n',
 tasks:[['Add a <select> with 2 <option>','2 <option> wala <select> jodo','select',/<select>[\s\S]*<option[\s\S]*<option[\s\S]*<\/select>/i],['Add a <textarea> message box','<textarea> message box jodo','textarea',/<textarea/i],['Add a checkbox with type="checkbox"','type="checkbox" wala checkbox jodo','checkbox',/type\s*=\s*["']checkbox["']/i]],
 tip:['Always connect a label to every input. It is better for phones and screen readers.','Har input ke saath label jodo. Phone aur screen reader ke liye behtar.']},
{t:['JavaScript: click and change','JavaScript: click karo aur badlo'],
 i:['JavaScript makes the page react. getElementById finds an element, addEventListener waits for a click, and textContent changes its text. Open the Console under the preview to see console.log messages.','JavaScript page ko react karwata hai. getElementById element dhoondhta hai, addEventListener click ka intezaar karta hai, aur textContent uska text badalta hai. console.log ke message dekhne ke liye preview ke neeche Console kholo.'],
 code:P+'  <style>\n    body { font-family: system-ui, sans-serif; text-align: center; padding-top: 40px; }\n    button { padding: 12px 22px; font-size: 18px; border-radius: 10px; border: 0; background: #12b886; color: white; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <h1 id="msg">Hello!</h1>\n  <button id="go">Click me</button>\n  <script>\n    const msg = document.getElementById("go");\n    const title = document.getElementById("msg");\n    msg.addEventListener("click", function () {\n      title.textContent = "You clicked the button!";\n      console.log("button clicked");\n    });\n  </script>\n</body>\n</html>\n',
 tasks:[['Change the message shown after the click','Click ke baad ka message badlo','textContent',/textContent\s*=\s*["'](?!You clicked the button!)[^"']+/i],['Change the colour on click: title.style.color = "red"','Click par rang badlo: title.style.color = "red"','style',/\.style\.color\s*=/i],['Add a second button with its own listener','Doosra button apne listener ke saath jodo','addEventListener',/(addEventListener[\s\S]*){2}/i]],
 tip:['If nothing happens, open the Console. Red messages tell you the line that has a problem.','Kuch na ho to Console kholo. Laal message batata hai kis line me dikkat hai.']},
{t:['JavaScript: counter and logic','JavaScript: counter aur logic'],
 i:['A variable remembers a value (let count = 0). A function groups steps. if and else make decisions. Here the counter changes colour when it passes 5.','Variable value yaad rakhta hai (let count = 0). Function kadam group karta hai. if aur else faisle lete hain. Yahan counter 5 paar karte hi rang badalta hai.'],
 code:P+'  <style>\n    body { font-family: system-ui, sans-serif; text-align: center; padding-top: 30px; }\n    #n { font-size: 72px; margin: 10px; }\n    button { font-size: 22px; padding: 10px 20px; margin: 4px; border-radius: 10px; border: 0; background: #5f3dc4; color: white; }\n  </style>\n</head>\n<body>\n  <div id="n">0</div>\n  <button onclick="change(1)">+1</button>\n  <button onclick="change(-1)">-1</button>\n  <button onclick="reset()">Reset</button>\n  <script>\n    let count = 0;\n    const out = document.getElementById("n");\n    function show() {\n      out.textContent = count;\n      if (count > 5) {\n        out.style.color = "crimson";\n      } else {\n        out.style.color = "black";\n      }\n    }\n    function change(step) { count = count + step; show(); }\n    function reset() { count = 0; show(); }\n  </script>\n</body>\n</html>\n',
 tasks:[['Add a +10 button','+10 wala button jodo','onclick',/change\(\s*10\s*\)/i],['Stop the counter going below 0 using if','if se counter ko 0 se neeche jane se roko','if',/if\s*\([^)]*(<|>)\s*0|Math\.max/i],['Change the colour limit from 5 to 8','Rang ki seema 5 se 8 karo','if',/count\s*>\s*8/i]],
 tip:['Break a problem into small functions. Each function should do one job.','Samasya ko chhote functions me todo. Har function ek hi kaam kare.']},
{t:['Responsive pages for mobile','Mobile ke liye responsive page'],
 i:['Most visitors use phones. The viewport meta tag lets the page fit the phone screen. @media applies rules only on small screens. Use the Mobile button above the preview to test.','Zyadatar visitors phone par aate hain. viewport meta tag page ko phone screen me fit karta hai. @media sirf chhoti screen par rules lagata hai. Test karne ke liye preview ke upar Mobile button dabao.'],
 code:P+'  <style>\n    * { box-sizing: border-box; }\n    body { font-family: system-ui, sans-serif; margin: 0; }\n    .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; padding: 16px; }\n    .tile { background: #74c0fc; padding: 40px 10px; text-align: center; border-radius: 10px; }\n    @media (max-width: 600px) {\n      .grid { grid-template-columns: 1fr; }\n    }\n  </style>\n</head>\n<body>\n  <div class="grid">\n    <div class="tile">1</div>\n    <div class="tile">2</div>\n    <div class="tile">3</div>\n  </div>\n</body>\n</html>\n',
 tasks:[['Make the phone layout use 2 columns (1fr 1fr)','Phone layout me 2 column karo (1fr 1fr)','grid-template-columns',/max-width[\s\S]*grid-template-columns\s*:\s*(1fr 1fr|repeat\(\s*2)/i],['Change the breakpoint to 700px','Breakpoint 700px karo','@media',/max-width\s*:\s*700px/i],['Add a 4th tile','4th tile jodo','tile',/(class\s*=\s*["']tile["'][\s\S]*){4}/i]],
 tip:['Design for the phone first, then add rules for bigger screens.','Pehle phone ke liye design karo, fir bade screen ke rules jodo.']},
{t:['Mini project: business card page','Mini project: business card page'],
 i:['Put everything together: a centered card with your name, a short bio, a link and a button that changes a message. Make it yours: colours, fonts, text. When it looks good, press Download and you have a real web page.','Sab kuch jodo: beech me ek card jisme aapka naam, chhota bio, link aur ek button jo message badle. Ise apna banao: rang, font, text. Accha lage to Download dabao, aapka asli web page taiyaar.'],
 code:P+'  <style>\n    * { box-sizing: border-box; }\n    body { margin: 0; min-height: 100vh; display: grid; place-items: center; font-family: system-ui, sans-serif; background: linear-gradient(135deg, #1b1f3b, #5f3dc4); }\n    .card { width: min(92vw, 340px); padding: 28px; border-radius: 20px; background: white; text-align: center; box-shadow: 0 20px 50px rgba(0,0,0,.35); }\n    .avatar { width: 84px; height: 84px; border-radius: 50%; background: #ffd43b; display: grid; place-items: center; font-size: 38px; margin: 0 auto 12px; }\n    h1 { margin: 6px 0; }\n    p { color: #555; line-height: 1.5; }\n    a { color: #5f3dc4; font-weight: 600; }\n    button { margin-top: 12px; padding: 10px 20px; border: 0; border-radius: 999px; background: #5f3dc4; color: white; font-size: 16px; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class="card">\n    <div class="avatar">R</div>\n    <h1>Your Name</h1>\n    <p>Instrument engineer who loves building things for the web.</p>\n    <a href="https://ourworldhive.com" target="_blank" rel="noopener">My website</a><br>\n    <button id="b">Say hello</button>\n    <p id="out"></p>\n  </div>\n  <script>\n    document.getElementById("b").addEventListener("click", function () {\n      document.getElementById("out").textContent = "Hello! Thanks for visiting.";\n    });\n  </script>\n</body>\n</html>\n',
 tasks:[['Replace "Your Name" and the bio with your own','"Your Name" aur bio apna likho','h1',/<h1>(?!Your Name<)[^<]+<\/h1>/i],['Change the page background gradient colours','Page ke background gradient ke rang badlo','background',/body\s*\{[^}]*linear-gradient\((?!135deg, #1b1f3b, #5f3dc4)/i],['Add a second link or button','Doosra link ya button jodo','a',/(<a |<button)[\s\S]*(<a |<button)[\s\S]*(<a |<button)/i]],
 tip:['Done! Press Download to save your page as index.html. You can upload it to any hosting.','Ho gaya! Download dabao aur apna page index.html ke roop me save karo. Kisi bhi hosting par upload kar sakte ho.']}
];
